def encode(s):
    if not s:
        return ''

    parts = []
    previous = s[0]
    count = 1

    for character in s[1:]:
        if character == previous:
            count += 1
        else:
            parts.append(previous + (str(count) if count > 1 else ''))
            previous = character
            count = 1

