    return ''.join(parts)


def decode(s):
    parts = []
    index = 0

    while index < len(s):
        character = s[index]
        index += 1
        count_start = index

        while index < len(s) and s[index].isdigit():
            index += 1

        count = int(s[count_start:index]) if index > count_start else 1
        parts.append(character * count)

    return ''.join(parts)
